<script>
'use strict';
const missions=[
{title:'The robot exhibition',core:[3,5],intro:'Build a cardboard robot for a weekend living-room exhibition. The shell looks simple. What else is hiding?',base:'Cut, decorate, and assemble a cardboard robot shell',facts:[
['The tangled cable','What makes the arms move?','The prototype needs a simple linkage, not just cardboard tubes.','Prototype and fit the arm linkage',[2,4],'Make it a static sculpture','The first exhibition will use a static pose; movable arms are out of scope.'],
['The old clock','When does the paint dry?','Drying adds waiting time, even when nobody is working.','Paint in two sessions and check the finish',[1,2],'Use coloured paper instead','Use coloured paper rather than paint. There is no drying wait.'],
['The little lock','How does it stand safely?','A tall top-heavy robot needs a wide base and a stability check.','Build a wide base and test the freestanding model',[1,3],'Use a tabletop format','Make a short tabletop model with a broad base and check that it sits securely.'],
['The missing bridge','How does it get through the door?','A finished robot that cannot leave the room is an accidental roommate.','Design detachable sections and rehearse assembly',[1,2],'Exhibit where it is built','Keep the exhibition in the build room. Transport is excluded.'],
['The tiny flag','What counts as finished?','A tour needs labels and one rehearsal, not just a dramatic unveiling.','Write labels and practise a two-minute tour',[1,2],'Show the robot only','A casual show-and-tell is enough. Printed labels and a rehearsed tour are excluded.']]},
{title:'The photo portal',core:[4,6],intro:'Make a small family photo website. A grid of pictures seems easy. Five questions are waiting under that grid.',base:'Build a responsive photo grid from prepared sample images',facts:[
['The tangled cable','What shape are the old files?','Some images are huge, rotated, or duplicates. A pretty grid does not fix the archive.','Inspect and prepare a representative batch of photos',[2,5],'Start with twelve curated photos','Only twelve hand-prepared photos are included. Archive cleanup is excluded.'],
['The old clock','What happens on a slow connection?','Full-resolution originals may leave a phone waiting.','Generate thumbnails and test loading behaviour',[2,4],'Ship a small offline album','Deliver a small offline album with prepared pictures. Live hosting is excluded.'],
['The little lock','Who may see these photos?','A public URL and a family-only album are different products.','Set up private access and test signed-out behaviour',[3,6],'Use public-safe sample photos','Use public-safe sample images only. Private family content is excluded.'],
['The missing bridge','Who will add the next album?','A working demo is not automatically an easy handover.','Write and rehearse a simple album publishing process',[2,3],'Treat this as a one-off album','Deliver one fixed album. A future upload workflow is excluded.'],
['The tiny flag','What if an upload goes wrong?','A mistaken replacement needs a way back.','Test a backup and restore process for the album',[1,3],'Keep it a disposable demo','This is a disposable demo from copies; originals remain untouched and separately stored.']]},
{title:'The treehouse observatory',core:[2,4],intro:'Set up a pretend observatory in an existing backyard playhouse. No construction: this expedition is about a removable cardboard telescope and a stargazing evening.',base:'Build and decorate a pretend cardboard telescope',facts:[
['The tangled cable','How will the telescope turn?','A tube glued in one direction has strong opinions about the sky.','Make a rotating cardboard cradle',[1,2],'Use a handheld tube','Use a handheld tube with no mounting hardware.'],
['The old clock','What if the sky is cloudy?','A stargazing party needs a cloudy-night plan.','Prepare an indoor paper-constellation activity',[1,2],'Choose an indoor-only evening','The first version is an indoor pretend observatory, independent of weather.'],
['The little lock','What happens after sunset?','An existing playhouse still needs an adult check and lighting before evening use.','Have an adult check the space and arrange gentle lighting',[1,2],'Keep the activity indoors','Use a familiar indoor room with existing lighting instead of the playhouse.'],
['The missing bridge','How will visitors find the stars?','The tube is a prop, not an optical instrument. A simple star chart does the teaching.','Make a readable seasonal star chart and practise using it',[1,3],'Explore imaginary planets','Make it a fictional space voyage; identifying real stars is excluded.'],
['The tiny flag','How does the evening end?','Packing away is part of the experience too.','Plan storage and pack the kit into one box',[.5,1],'Use the supplies already on hand','Keep only a reusable tube and paper chart in an existing supplies drawer.']]}
];
const $=id=>document.getElementById(id);
let mi=0,active=-1,seen=new Set(),choices=new Map();
const fmt=n=>Number(n.toFixed(2)).toLocaleString(undefined,{maximumFractionDigits:2});
const range=(lo,hi)=>lo===hi?fmt(lo)+' h':fmt(lo)+'–'+fmt(hi)+' h';
function totals(){const m=missions[mi];let lo=m.core[0],hi=m.core[1];for(const i of seen){if(choices.get(i)!=='trim'){lo+=m.facts[i][4][0];hi+=m.facts[i][4][1];}}return [lo,hi];}
function render(){
const m=missions[mi],t=totals();
$('count').textContent=seen.size+' / 5 explored';$('progress').style.width=(seen.size*20)+'%';
$('base').textContent=range(...m.core);$('scope').textContent=range(...t);
$('scopeLabel').textContent=seen.size===5?'All five questions considered':seen.size===0?'Hidden work not yet investigated':'Partial scope: '+(5-seen.size)+' questions remain';
document.querySelectorAll('.hotspot').forEach((b,i)=>{b.setAttribute('aria-pressed',String(seen.has(i)));b.classList.toggle('active',i===active);b.textContent=seen.has(i)?'✓':i+1;});
const fact=$('fact');fact.replaceChildren();
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;n.textContent=text;return n;}
if(active<0){fact.append(el('div','factlabel','The first impression'),el('h2','',m.title),el('p','',m.intro),el('p','small','Investigate each chamber. Keep the extra work or explicitly simplify the brief.'));}
else{
const f=m.facts[active];fact.append(el('div','factlabel','Question '+(active+1)+' / '+f[0]),el('h2','',f[1]),el('p','',f[2]),el('p','small','Keep it: '+f[3]+' · '+range(...f[4])+' extra effort.'));
if(mi===0&&active===1)fact.append(el('p','small','Drying may add an overnight wait. The range counts hands-on effort only.'));
const buttons=el('div','choice','');
[['keep','Keep the work'],['trim',f[5]]].forEach(([value,label])=>{const b=el('button','',label);b.type='button';b.setAttribute('aria-pressed',String((choices.get(active)||'keep')===value));b.onclick=()=>{choices.set(active,value);render();};buttons.append(b);});fact.append(buttons);
if(choices.get(active)==='trim')fact.append(el('p','small',f[6]));
}
const remaining=[0,1,2,3,4].find(i=>!seen.has(i));
$('next').textContent=remaining===undefined?'Survey complete ✓':'Dive into question '+(remaining+1)+' ↓';$('next').disabled=remaining===undefined;
$('insight').textContent=seen.size===5?'Your scope is now explained, not magically certain. Keep the assumptions with the number; revisit both when reality changes.':seen.size?'Notice how an explicit exclusion can shrink the work without pretending it does not exist.':'A small number is not necessarily a bad estimate. An unexplained number is simply hard to trust.';
}
function explore(i){active=i;seen.add(i);render();}
document.querySelectorAll('.hotspot').forEach(b=>b.onclick=()=>explore(Number(b.dataset.i)));
$('next').onclick=()=>{const i=[0,1,2,3,4].find(i=>!seen.has(i));if(i!==undefined)explore(i);};
function reset(){active=-1;seen=new Set();choices=new Map();render();}
$('reset').onclick=reset;$('mission').onchange=()=>{mi=Number($('mission').value);reset();};
function calculate(){
const text=$('prose').value;let lo=0,hi=0,count=0,errors=[];
for(const match of text.matchAll(/\[([^\]\n]*)\]/g)){
const m=match[1].match(/^\s*(\d+(?:\.\d+)?)\s*(?:\.\.\s*(\d+(?:\.\d+)?)\s*)?h\s*$/i);
if(!m){errors.push('Unrecognised bracket: ['+match[1]+']. Use [2..5h] or [2h].');continue;}
const a=Number(m[1]),b=m[2]===undefined?a:Number(m[2]);
if(!Number.isFinite(a)||!Number.isFinite(b)||a>b||a>100000||b>100000){errors.push('Check ['+match[1]+']: use an ascending range, at most 100,000 hours.');continue;}
lo+=a;hi+=b;count++;
}
$('total').textContent=count?range(lo,hi):'No effort ranges yet';
$('parts').textContent=count+' embedded '+(count===1?'range':'ranges')+(errors.length?' · invalid brackets excluded':'');
$('validation').textContent=errors[0]||'';
return {lo,hi,count,errors};
}
$('prose').addEventListener('input',calculate);
$('load').onclick=()=>{
const m=missions[mi];let lines=[m.title+' — scope survey','I am assuming the first version includes: '+m.base.toLowerCase()+'. ['+m.core.join('..')+'h]'];
for(let i=0;i<5;i++){
const f=m.facts[i];
lines.push(!seen.has(i)?'Not investigated yet: '+f[1]+' This is still an open assumption, not zero effort.':choices.get(i)==='trim'?f[6]:f[1]+' '+f[2]+' I will '+f[3].charAt(0).toLowerCase()+f[3].slice(1)+'. ['+f[4].join('..')+'h]');
}
lines.push('These are illustrative effort ranges, not a delivery promise. Waiting time and dependencies need a separate calendar discussion. I will revisit this estimate after a first prototype.');
$('prose').value=lines.join('\n\n');calculate();$('prose').focus();
};
$('download').onclick=()=>{
const t=calculate(),content=$('prose').value+'\n\nEmbedded effort total: '+(t.count?range(t.lo,t.hi):'not specified')+'\n'+(t.errors.length?'Some bracketed ranges could not be counted.\n':'')+'Effort ranges are illustrative, not confidence intervals or delivery dates.\n';
const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='literate-estimate.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
};
render();calculate();
</script></body></html>
